// Extrai repositórios do GitHub de mensagens, legendas e hiperlinks do Telegram
const items = [];
const incoming = $input.all();

for (const item of incoming) {
  const data = item.json;
  const msg = data.channel_post || data.message || data.edited_channel_post || data;
  const rawText = msg.text || msg.caption || data.text || '';
  const entities = msg.entities || msg.caption_entities || [];

  const foundUrls = [];

  // 1. Extrair de hiperlinks nas entidades (formatação markdown)
  for (const entity of entities) {
    if (entity.type === 'text_link' && entity.url) {
      foundUrls.push(entity.url);
    }
  }

  // 2. Extrair URLs do GitHub do texto puro
  const githubRegex = /(?:https?:\/\/)?(?:www\.)?github\.com\/([a-zA-Z0-9._-]+)\/([a-zA-Z0-9._-]+)/gi;
  let match;
  while ((match = githubRegex.exec(rawText)) !== null) {
    const owner = match[1];
    const repo = match[2].replace(/\.git$/i, '');
    foundUrls.push(`https://github.com/${owner}/${repo}`);
  }

  for (const u of foundUrls) {
    const m = /(?:https?:\/\/)?(?:www\.)?github\.com\/([a-zA-Z0-9._-]+)\/([a-zA-Z0-9._-]+)/i.exec(u);
    if (m) {
      foundUrls.push(`https://github.com/${m[1]}/${m[2].replace(/\.git$/i, '')}`);
    }
  }

  // 3. Deduplicar na mesma mensagem
  const uniqueRepos = [...new Set(foundUrls.filter(u => u.includes('github.com/')))];

  for (const repo of uniqueRepos) {
    items.push({
      json: {
        repo: repo,
        text: rawText,
        source: 'telegram',
        chat_id: msg.chat ? msg.chat.id : null,
        message_id: msg.message_id || null,
        sender: msg.from ? (msg.from.username || msg.from.first_name) : (msg.chat ? msg.chat.title : 'Telegram')
      }
    });
  }
}

return items;
